        def keccak_f1600(self, a):

            def rol64(x, n):
                x &= 0xffff_ffff_ffff_ffff
                n &= 63
                if n == 0:
                    return x
                return ((x << n) | (x >> (64 - n))) & 0xffff_ffff_ffff_ffff

            for rnd in range(24):
                # Theta
                c = [0] * 5
                for x in range(5):
                    c[x] = a[x] ^ a[x + 5] ^ a[x + 10] ^ a[x + 15] ^ a[x + 20]
                d = [0] * 5
                for x in range(5):
                    d[x] = c[(x - 1) % 5] ^ rol64(c[(x + 1) % 5], 1)
                for y in range(5):
                    for x in range(5):
                        a[x + 5 * y] ^= d[x]

                # Rho + Pi
                b = [0] * 25
                for y in range(5):
                    for x in range(5):
                        idx = x + 5 * y
                        rot = self.rho[idx]
                        v = rol64(a[idx], rot)
                        x2 = y
                        y2 = (2 * x + 3 * y) % 5
                        b[x2 + 5 * y2] = v

                # Chi
                for y in range(5):
                    row = [b[x + 5 * y] for x in range(5)]
                    for x in range(5):
                        a[x + 5 * y] = row[x] ^ ((~row[(x + 1) % 5]) & row[(x + 2) % 5])

                # Iota
                a[0] ^= self.rc[rnd]
