            other = self.__class__(b"", self.custom)
            other.rate = self.rate
            other.suffix = self.suffix
            other.output_bits = self.output_bits
            other.state = list(self.state)
            other.buf = bytearray(self.buf)
            other.finalized = self.finalized
            return other

