                c = [0] * 5
                for x in range(5):
                    c[x] = a[x] ^ a[x + 5] ^ a[x + 10] ^ a[x + 15] ^ a[x + 20]
                d = [0] * 5
                for x in range(5):
                    d[x] = c[(x - 1) % 5] ^ rol64(c[(x + 1) % 5], 1)
                for y in range(5):
                    for x in range(5):
                        a[x + 5 * y] ^= d[x]

