                b = [0] * 25
                for y in range(5):
                    for x in range(5):
                        idx = x + 5 * y
                        rot = self.rho[idx]
                        v = rol64(a[idx], rot)
                        x2 = y
                        y2 = (2 * x + 3 * y) % 5
                        b[x2 + 5 * y2] = v

