                h[b2 + 32] |= (uint8_t)(((v1 >> 2) & 1) << sh);
                h[b2 + 64] |= (uint8_t)(((v1 >> 1) & 1) << sh);
                h[b2 + 96] |= (uint8_t)((v1 & 1) << sh);
