            off = 0
            length = n
            while length >= 128:
                x = (self.ror64(x + y + v0 + self.u64le(data, off + 8), 37) * self.k1) & 0xffff_ffff_ffff_ffff
                y = (self.ror64(y + v1 + self.u64le(data, off + 48), 42) * self.k1) & 0xffff_ffff_ffff_ffff
                x ^= w1
                y = (y + v0 + self.u64le(data, off + 40)) & 0xffff_ffff_ffff_ffff
