        @classmethod
        def ensure_tables(cls):
            t0, t1, t2, t3 = [], [], [], []
            for i in range(256):
                s = cls.sbox[i]
                s2 = ((s << 1) ^ 0x1b) & 0xff if (s & 0x80) else (s << 1)
                s3 = s2 ^ s
                t0.append((s2, s, s, s3))
                t1.append((s3, s2, s, s))
                t2.append((s, s3, s2, s))
                t3.append((s, s, s3, s2))
            Hash.ECHOBase.T0 = tuple(t0)
            Hash.ECHOBase.T1 = tuple(t1)
            Hash.ECHOBase.T2 = tuple(t2)
            Hash.ECHOBase.T3 = tuple(t3)
            return

        def __init__(self, data=b"", salt=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            if not isinstance(salt, (bytes, bytearray, memoryview)):
                raise TypeError("salt must be bytes-like")
            if len(salt) not in (0, 16):
                raise ValueError("salt must be 16 bytes or empty")
            if len(salt) == 0:
                self.salt = bytearray(16)
            else:
                self.salt = bytearray(salt)
            self.buf = bytearray()
            self.msg_len = 0
            self.total_bits = 0
            word = self.hash_size.to_bytes(2, "little") + b"\x00" * 14
            self.v = bytearray(word * self.cv_words)
            self.ensure_tables()
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.salt = bytearray(self.salt)
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            other.total_bits = self.total_bits
            other.v = bytearray(self.v)
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            if not data:
                return self
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                Ci = self.total_bits + self.block_size * 8
                self.compress(block, Ci)
                self.total_bits = Ci
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return bytes(c.v[:self.digest_size])

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            L = self.msg_len * 8
            block_bytes = self.block_size
            pos = len(self.buf)
            total = self.total_bits + pos * 8
            if total != L:
                raise AssertionError("internal length mismatch")

            self.buf.append(0x80)
            pos += 1

            processed_extra = False
            if pos > block_bytes - 18:
                if pos < block_bytes:
                    self.buf.extend(b"\x00" * (block_bytes - pos))
                self.compress(bytes(self.buf[:block_bytes]), total)
                processed_extra = True
                self.buf = bytearray()
                pos = 0

            if pos < block_bytes - 18:
                self.buf.extend(b"\x00" * (block_bytes - 18 - pos))

            self.buf.extend(self.hash_size.to_bytes(2, "little"))
            self.buf.extend(L.to_bytes(16, "little"))

            if len(self.buf) != block_bytes:
                raise AssertionError("final block size mismatch")

            Ci = total if (not processed_extra and L != self.total_bits) else 0
            self.compress(bytes(self.buf), Ci)

            self.buf = bytearray()
            self.total_bits = total
            return

        def compress(self, block, Ci):
            v_words = [list(self.v[i * 16:(i + 1) * 16]) for i in range(self.cv_words)]
            m_words = [list(block[i * 16:(i + 1) * 16]) for i in range(self.msg_words)]

            w = [None] * 16
            for i in range(self.cv_words):
                w[i] = v_words[i][:]
            for i in range(self.msg_words):
                w[self.cv_words + i] = m_words[i][:]

            counter = (Ci & 0xffff_ffff_ffff_ffff) if Ci else 0

            for _ in range(self.rounds):
                counter = self.sub_words(w, counter)
                self.shift_rows_words(w)
                self.mix_columns_words(w)

            out_words = []
            if self.cv_words == 4:
                for r in range(4):
                    tmp = [0] * 16
                    for j in range(16):
                        tmp[j] = (
                            v_words[r][j] ^
                            m_words[r][j] ^
                            m_words[r + 4][j] ^
                            m_words[r + 8][j] ^
                            w[r][j] ^
                            w[r + 4][j] ^
                            w[r + 8][j] ^
                            w[r + 12][j]
                        ) & 0xff
                    out_words.append(tmp)
            else:
                for r in range(8):
                    tmp = [0] * 16
                    for j in range(16):
                        tmp[j] = (
                            v_words[r][j] ^
                            m_words[r][j] ^
                            w[r][j] ^
                            w[r + 8][j]
                        ) & 0xff
                    out_words.append(tmp)

            self.v = bytearray(sum(out_words, []))
            return

        def sub_words(self, w, counter):
            k = counter & 0xffff_ffff_ffff_ffff
            salt_key = list(self.salt)
            for i in range(16):
                k1 = list(k.to_bytes(8, "little") + b"\x00" * 8)
                w[i] = self.aes_round(w[i], k1)
                w[i] = self.aes_round(w[i], salt_key)
                k = (k + 1) & 0xffff_ffff_ffff_ffff
            return k

        def aes_round(self, state, rk):
            t0 = self.T0
            t1 = self.T1
            t2 = self.T2
            t3 = self.T3
            v0 = t0[state[0]]
            v1 = t1[state[5]]
            v2 = t2[state[10]]
            v3 = t3[state[15]]
            c0 = v0[0] ^ v1[0] ^ v2[0] ^ v3[0] ^ rk[0]
            c1 = v0[1] ^ v1[1] ^ v2[1] ^ v3[1] ^ rk[1]
            c2 = v0[2] ^ v1[2] ^ v2[2] ^ v3[2] ^ rk[2]
            c3 = v0[3] ^ v1[3] ^ v2[3] ^ v3[3] ^ rk[3]
            v0 = t0[state[4]]
            v1 = t1[state[9]]
            v2 = t2[state[14]]
            v3 = t3[state[3]]
            c4 = v0[0] ^ v1[0] ^ v2[0] ^ v3[0] ^ rk[4]
            c5 = v0[1] ^ v1[1] ^ v2[1] ^ v3[1] ^ rk[5]
            c6 = v0[2] ^ v1[2] ^ v2[2] ^ v3[2] ^ rk[6]
            c7 = v0[3] ^ v1[3] ^ v2[3] ^ v3[3] ^ rk[7]
            v0 = t0[state[8]]
            v1 = t1[state[13]]
            v2 = t2[state[2]]
            v3 = t3[state[7]]
            c8 = v0[0] ^ v1[0] ^ v2[0] ^ v3[0] ^ rk[8]
            c9 = v0[1] ^ v1[1] ^ v2[1] ^ v3[1] ^ rk[9]
            c10 = v0[2] ^ v1[2] ^ v2[2] ^ v3[2] ^ rk[10]
            c11 = v0[3] ^ v1[3] ^ v2[3] ^ v3[3] ^ rk[11]
            v0 = t0[state[12]]
            v1 = t1[state[1]]
            v2 = t2[state[6]]
            v3 = t3[state[11]]
            c12 = v0[0] ^ v1[0] ^ v2[0] ^ v3[0] ^ rk[12]
            c13 = v0[1] ^ v1[1] ^ v2[1] ^ v3[1] ^ rk[13]
            c14 = v0[2] ^ v1[2] ^ v2[2] ^ v3[2] ^ rk[14]
            c15 = v0[3] ^ v1[3] ^ v2[3] ^ v3[3] ^ rk[15]
            return [c0, c1, c2, c3, c4, c5, c6, c7, c8, c9, c10, c11, c12, c13, c14, c15]

        def shift_rows_words(self, w):
            w[1], w[5], w[9], w[13] = w[5], w[9], w[13], w[1]
            w[2], w[6], w[10], w[14] = w[10], w[14], w[2], w[6]
            w[3], w[7], w[11], w[15] = w[15], w[3], w[7], w[11]
            return

        def mix_columns_words(self, w):

            def xtime8(x):
                return ((x << 1) ^ 0x1b) & 0xff if (x & 0x80) else (x << 1)

            def mix_column4(a0, a1, a2, a3):
                t = (a0 ^ a1 ^ a2 ^ a3) & 0xff
                u = a0
                return (
                    (a0 ^ t ^ xtime8(a0 ^ a1)) & 0xff,
                    (a1 ^ t ^ xtime8(a1 ^ a2)) & 0xff,
                    (a2 ^ t ^ xtime8(a2 ^ a3)) & 0xff,
                    (a3 ^ t ^ xtime8(a3 ^ u)) & 0xff,
                )

            for col in range(4):
                base = col * 4
                for b in range(16):
                    r0, r1, r2, r3 = mix_column4(
                        w[base][b], w[base + 1][b], w[base + 2][b], w[base + 3][b]
                    )
                    w[base][b] = r0
                    w[base + 1][b] = r1
                    w[base + 2][b] = r2
                    w[base + 3][b] = r3
            return

