    class LaneBase:
        sbox = (
            0x63, 0x7c, 0x77, 0x7b, 0xf2, 0x6b, 0x6f, 0xc5, 0x30, 0x01, 0x67, 0x2b, 0xfe, 0xd7, 0xab, 0x76,
            0xca, 0x82, 0xc9, 0x7d, 0xfa, 0x59, 0x47, 0xf0, 0xad, 0xd4, 0xa2, 0xaf, 0x9c, 0xa4, 0x72, 0xc0,
            0xb7, 0xfd, 0x93, 0x26, 0x36, 0x3f, 0xf7, 0xcc, 0x34, 0xa5, 0xe5, 0xf1, 0x71, 0xd8, 0x31, 0x15,
            0x04, 0xc7, 0x23, 0xc3, 0x18, 0x96, 0x05, 0x9a, 0x07, 0x12, 0x80, 0xe2, 0xeb, 0x27, 0xb2, 0x75,
            0x09, 0x83, 0x2c, 0x1a, 0x1b, 0x6e, 0x5a, 0xa0, 0x52, 0x3b, 0xd6, 0xb3, 0x29, 0xe3, 0x2f, 0x84,
            0x53, 0xd1, 0x00, 0xed, 0x20, 0xfc, 0xb1, 0x5b, 0x6a, 0xcb, 0xbe, 0x39, 0x4a, 0x4c, 0x58, 0xcf,
            0xd0, 0xef, 0xaa, 0xfb, 0x43, 0x4d, 0x33, 0x85, 0x45, 0xf9, 0x02, 0x7f, 0x50, 0x3c, 0x9f, 0xa8,
            0x51, 0xa3, 0x40, 0x8f, 0x92, 0x9d, 0x38, 0xf5, 0xbc, 0xb6, 0xda, 0x21, 0x10, 0xff, 0xf3, 0xd2,
            0xcd, 0x0c, 0x13, 0xec, 0x5f, 0x97, 0x44, 0x17, 0xc4, 0xa7, 0x7e, 0x3d, 0x64, 0x5d, 0x19, 0x73,
            0x60, 0x81, 0x4f, 0xdc, 0x22, 0x2a, 0x90, 0x88, 0x46, 0xee, 0xb8, 0x14, 0xde, 0x5e, 0x0b, 0xdb,
            0xe0, 0x32, 0x3a, 0x0a, 0x49, 0x06, 0x24, 0x5c, 0xc2, 0xd3, 0xac, 0x62, 0x91, 0x95, 0xe4, 0x79,
            0xe7, 0xc8, 0x37, 0x6d, 0x8d, 0xd5, 0x4e, 0xa9, 0x6c, 0x56, 0xf4, 0xea, 0x65, 0x7a, 0xae, 0x08,
            0xba, 0x78, 0x25, 0x2e, 0x1c, 0xa6, 0xb4, 0xc6, 0xe8, 0xdd, 0x74, 0x1f, 0x4b, 0xbd, 0x8b, 0x8a,
            0x70, 0x3e, 0xb5, 0x66, 0x48, 0x03, 0xf6, 0x0e, 0x61, 0x35, 0x57, 0xb9, 0x86, 0xc1, 0x1d, 0x9e,
            0xe1, 0xf8, 0x98, 0x11, 0x69, 0xd9, 0x8e, 0x94, 0x9b, 0x1e, 0x87, 0xe9, 0xce, 0x55, 0x28, 0xdf,
            0x8c, 0xa1, 0x89, 0x0d, 0xbf, 0xe6, 0x42, 0x68, 0x41, 0x99, 0x2d, 0x0f, 0xb0, 0x54, 0xbb, 0x16,
        )

        @classmethod
        def ensure_tables(self):
            if hasattr(Hash.LaneBase, "k_table"):
                return

            k = [0] * 768
            k[0] = 0x07fc_703d
            for i in range(1, 768):
                prev = k[i - 1]
                v = prev >> 1
                if prev & 1:
                    v ^= 0xd000_0001
                k[i] = v & 0xffff_ffff
            Hash.LaneBase.k_table = tuple(k)

            kb = [0] * (768 * 4)
            p = 0
            for word in k:
                kb[p] = (word >> 24) & 0xff
                kb[p + 1] = (word >> 16) & 0xff
                kb[p + 2] = (word >> 8) & 0xff
                kb[p + 3] = word & 0xff
                p += 4
            Hash.LaneBase.k_bytes = tuple(kb)

            m2 = [0] * 256
            m3 = [0] * 256
            for a in range(256):
                b = a << 1
                if a & 0x80:
                    b ^= 0x11b
                b &= 0xff
                m2[a] = b
                m3[a] = b ^ a
            Hash.LaneBase.mul2_table = tuple(m2)
            Hash.LaneBase.mul3_table = tuple(m3)
            return

        def __init__(self, data=b''):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.databitcount = 0
            self.finalized = False
            self.final_digest = None
            self.ensure_tables()
            self.initialize()
            if data:
                self.update(data)
            return

        def initialize(self):
            self.hash = bytearray(64)
            self.buffer = bytearray(128)
            self.buffer[0] = 2
            self.buffer[1] = (self.digest_bits >> 24) & 0xff
            self.buffer[2] = (self.digest_bits >> 16) & 0xff
            self.buffer[3] = (self.digest_bits >> 8) & 0xff
            self.buffer[4] = (self.digest_bits >> 0) & 0xff
            if self.digest_bits <= 256:
                self.lane256_transform(self.buffer, 0)
            else:
                self.lane512_transform(self.buffer, 0)
            return

        def copy(self):
            other = self.__class__()
            other.databitcount = self.databitcount
            other.buffer[:] = self.buffer
            other.hash[:] = self.hash
            other.finalized = self.finalized
            other.final_digest = self.final_digest
            return other

        def update(self, data):
            if self.finalized:
                raise ValueError("hash object already finalized")
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")

            mv = data if isinstance(data, memoryview) else memoryview(data)
            blocksize = self.block_size
            total = len(mv)
            offset = 0
            buffill = (self.databitcount >> 3) & (blocksize - 1)

            if buffill:
                n = blocksize - buffill
                if n > total:
                    n = total
                self.buffer[buffill:buffill + n] = mv[:n]
                self.databitcount += n << 3
                if buffill + n == blocksize:
                    if blocksize == 64:
                        self.lane256_transform(self.buffer, self.databitcount)
                    else:
                        self.lane512_transform(self.buffer, self.databitcount)
                offset = n

            remain = total - offset
            while remain >= blocksize:
                self.databitcount += blocksize << 3
                block = mv[offset:offset + blocksize]
                if blocksize == 64:
                    self.lane256_transform(block, self.databitcount)
                else:
                    self.lane512_transform(block, self.databitcount)
                offset += blocksize
                remain -= blocksize

            if remain:
                self.buffer[:remain] = mv[offset:offset + remain]
                self.databitcount += remain << 3
            return

        def digest(self):
            if self.finalized:
                return self.final_digest
            tmp = self.copy()
            tmp.finalize()
            return tmp.final_digest

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            if self.finalized:
                return

            blocksize = self.block_size
            used = (self.databitcount >> 3) & (blocksize - 1)

            if used:
                self.buffer[used:blocksize] = b'\x00' * (blocksize - used)
                if blocksize == 64:
                    self.lane256_transform(self.buffer, self.databitcount)
                else:
                    self.lane512_transform(self.buffer, self.databitcount)

            self.buffer[:blocksize] = b'\x00' * blocksize
            counter = self.databitcount & 0xffff_ffff_ffff_ffff
            self.buffer[1] = (counter >> 56) & 0xff
            self.buffer[2] = (counter >> 48) & 0xff
            self.buffer[3] = (counter >> 40) & 0xff
            self.buffer[4] = (counter >> 32) & 0xff
            self.buffer[5] = (counter >> 24) & 0xff
            self.buffer[6] = (counter >> 16) & 0xff
            self.buffer[7] = (counter >> 8) & 0xff
            self.buffer[8] = counter & 0xff

            if blocksize == 64:
                self.lane256_transform(self.buffer, 0)
            else:
                self.lane512_transform(self.buffer, 0)

            self.final_digest = bytes(self.hash[:self.digest_size])
            self.finalized = True
            return

        def lane256_transform(self, buffer, counter):

            def add_constants_2(r, a):
                kb = self.k_bytes
                base = 32 * r
                for block in range(2):
                    a_base = block * 16
                    w_base = base + block * 16
                    for col in range(4):
                        w = w_base + col * 4
                        a[a_base + col] ^= kb[w]
                        a[a_base + col + 4] ^= kb[w + 1]
                        a[a_base + col + 8] ^= kb[w + 2]
                        a[a_base + col + 12] ^= kb[w + 3]
                return

            def sub_shift_mix_2(a):
                s = self.sbox
                m2 = self.mul2_table
                m3 = self.mul3_table
                shifted = (0, 1, 2, 3, 5, 6, 7, 4, 10, 11, 8, 9, 15, 12, 13, 14)
                for p in (0, 16):
                    x = [s[a[p + i]] for i in shifted]
                    for col in range(4):
                        x0 = x[col]
                        x1 = x[4 + col]
                        x2 = x[8 + col]
                        x3 = x[12 + col]
                        a[p + col] = m2[x0] ^ m3[x1] ^ x2 ^ x3
                        a[p + 4 + col] = m2[x1] ^ m3[x2] ^ x3 ^ x0
                        a[p + 8 + col] = m2[x2] ^ m3[x3] ^ x0 ^ x1
                        a[p + 12 + col] = m2[x3] ^ m3[x0] ^ x1 ^ x2
                return

            def swap_columns256(a):
                p0, p1 = 0, 16
                for row in range(0, 16, 4):
                    for col0, col1 in ((2, 0), (3, 1)):
                        a[p0 + row + col0], a[p1 + row + col1] = a[p1 + row + col1], a[p0 + row + col0]
                return

            def xor_state_2(a, b):
                for i in range(32):
                    a[i] ^= b[i]
                return

            def expand_message256(hashval, buffer, w0, w1, w2, w3, w4, w5):
                for col in range(4):
                    bc = col * 4
                    for row in range(4):
                        idx = bc + row
                        pos = row * 4 + col
                        h0, h1 = hashval[idx], hashval[idx + 16]
                        b0, b1, b2, b3 = buffer[idx], buffer[idx + 16], buffer[idx + 32], buffer[idx + 48]
                        w0[pos], w0[pos + 16] = h0 ^ b0 ^ b1 ^ b2 ^ b3, h1 ^ b0 ^ b2
                        w1[pos], w1[pos + 16] = h0 ^ h1 ^ b0 ^ b2 ^ b3, h0 ^ b1 ^ b2
                        w2[pos], w2[pos + 16] = h0 ^ h1 ^ b0 ^ b1 ^ b2, h0 ^ b0 ^ b3
                        w3[pos], w3[pos + 16] = h0, h1
                        w4[pos], w4[pos + 16] = b0, b1
                        w5[pos], w5[pos + 16] = b2, b3
                return

            def store_hash256(hashval, w0):
                for col in range(4):
                    bc = col * 4
                    for row in range(4):
                        pos = row * 4 + col
                        hashval[bc + row] = w0[pos]
                        hashval[16 + bc + row] = w0[16 + pos]
                return

            def permute_p256(j, a, c0, c1, c2, c3, c4, c5, c6, c7):
                for i in range(5):
                    r = 5 * j + i
                    sub_shift_mix_2(a)
                    add_constants_2(r, a)
                    if r & 1:
                        a[3], a[7], a[11], a[15] = a[3] ^ c4, a[7] ^ c5, a[11] ^ c6, a[15] ^ c7
                    else:
                        a[3], a[7], a[11], a[15] = a[3] ^ c0, a[7] ^ c1, a[11] ^ c2, a[15] ^ c3
                    swap_columns256(a)
                sub_shift_mix_2(a)
                swap_columns256(a)
                return

            def permute_q256(j, a, c0, c1, c2, c3, c4, c5, c6, c7):
                for i in range(2):
                    r = 30 + 2 * j + i
                    sub_shift_mix_2(a)
                    add_constants_2(r, a)
                    if r & 1:
                        a[3], a[7], a[11], a[15] = a[3] ^ c4, a[7] ^ c5, a[11] ^ c6, a[15] ^ c7
                    else:
                        a[3], a[7], a[11], a[15] = a[3] ^ c0, a[7] ^ c1, a[11] ^ c2, a[15] ^ c3
                    swap_columns256(a)
                sub_shift_mix_2(a)
                swap_columns256(a)
                return

            w0 = [0] * 32
            w1 = [0] * 32
            w2 = [0] * 32
            w3 = [0] * 32
            w4 = [0] * 32
            w5 = [0] * 32

            expand_message256(self.hash, buffer, w0, w1, w2, w3, w4, w5)

            c0 = (counter >> 56) & 0xff
            c1 = (counter >> 48) & 0xff
            c2 = (counter >> 40) & 0xff
            c3 = (counter >> 32) & 0xff
            c4 = (counter >> 24) & 0xff
            c5 = (counter >> 16) & 0xff
            c6 = (counter >> 8) & 0xff
            c7 = counter & 0xff

            permute_p256(0, w0, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p256(1, w1, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p256(2, w2, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p256(3, w3, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p256(4, w4, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p256(5, w5, c0, c1, c2, c3, c4, c5, c6, c7)

            xor_state_2(w0, w1)
            xor_state_2(w0, w2)
            xor_state_2(w3, w4)
            xor_state_2(w3, w5)

            permute_q256(0, w0, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_q256(1, w3, c0, c1, c2, c3, c4, c5, c6, c7)

            xor_state_2(w0, w3)
            store_hash256(self.hash, w0)
            return

        def lane512_transform(self, buffer, counter):

            def add_constants_4(r, a):
                kb = self.k_bytes
                base = 64 * r
                for part in range(4):
                    a_base = part * 16
                    w_base = base + part * 16
                    for col in range(4):
                        w = w_base + col * 4
                        a[a_base + col] ^= kb[w]
                        a[a_base + col + 4] ^= kb[w + 1]
                        a[a_base + col + 8] ^= kb[w + 2]
                        a[a_base + col + 12] ^= kb[w + 3]
                return

            def sub_shift_mix_4(a):
                s = self.sbox
                m2 = self.mul2_table
                m3 = self.mul3_table
                shifted = (0, 1, 2, 3, 5, 6, 7, 4, 10, 11, 8, 9, 15, 12, 13, 14)
                for part in range(4):
                    p = part * 16
                    x = [s[a[p + i]] for i in shifted]
                    for col in range(4):
                        x0 = x[col]
                        x1 = x[4 + col]
                        x2 = x[8 + col]
                        x3 = x[12 + col]
                        a[p + col] = m2[x0] ^ m3[x1] ^ x2 ^ x3
                        a[p + 4 + col] = m2[x1] ^ m3[x2] ^ x3 ^ x0
                        a[p + 8 + col] = m2[x2] ^ m3[x3] ^ x0 ^ x1
                        a[p + 12 + col] = m2[x3] ^ m3[x0] ^ x1 ^ x2
                return

            def swap_columns512(a):
                bases = (0, 16, 32, 48)
                for row_base in range(0, 16, 4):
                    for src_block in range(4):
                        for dst_block in range(src_block + 1, 4):
                            src_index = bases[src_block] + row_base + dst_block
                            dst_index = bases[dst_block] + row_base + src_block
                            a[src_index], a[dst_index] = a[dst_index], a[src_index]
                return

            def xor_state_4(a, b):
                for i in range(64):
                    a[i] ^= b[i]
                return

            def expand_message512(hashval, buffer, w0, w1, w2, w3, w4, w5):
                for col in range(4):
                    bc = col * 4
                    for row in range(4):
                        idx = bc + row
                        pos = row * 4 + col
                        h0, h1, h2, h3 = hashval[idx], hashval[idx + 16], hashval[idx + 32], hashval[idx + 48]
                        b0, b1, b2, b3 = buffer[idx], buffer[idx + 16], buffer[idx + 32], buffer[idx + 48]
                        b4, b5, b6, b7 = buffer[idx + 64], buffer[idx + 80], buffer[idx + 96], buffer[idx + 112]
                        w0[pos], w0[pos + 16] = h0 ^ b0 ^ b2 ^ b4 ^ b6, h1 ^ b1 ^ b3 ^ b5 ^ b7
                        w1[pos], w1[pos + 16] = h0 ^ h2 ^ b0 ^ b4 ^ b6, h1 ^ h3 ^ b1 ^ b5 ^ b7
                        w2[pos], w2[pos + 16] = h0 ^ h2 ^ b0 ^ b2 ^ b4, h1 ^ h3 ^ b1 ^ b3 ^ b5
                        w3[pos], w3[pos + 16] = h0, h1
                        w4[pos], w4[pos + 16] = b0, b1
                        w5[pos], w5[pos + 16] = b4, b5
                        w0[pos + 32], w0[pos + 48] = h2 ^ b0 ^ b4, h3 ^ b1 ^ b5
                        w1[pos + 32], w1[pos + 48] = h0 ^ b2 ^ b4, h1 ^ b3 ^ b5
                        w2[pos + 32], w2[pos + 48] = h0 ^ b0 ^ b6, h1 ^ b1 ^ b7
                        w3[pos + 32], w3[pos + 48] = h2, h3
                        w4[pos + 32], w4[pos + 48] = b2, b3
                        w5[pos + 32], w5[pos + 48] = b6, b7
                return

            def store_hash512(hashval, w0):
                for col in range(4):
                    bc = col * 4
                    for row in range(4):
                        pos = row * 4 + col
                        hashval[bc + row] = w0[pos]
                        hashval[16 + bc + row] = w0[16 + pos]
                        hashval[32 + bc + row] = w0[32 + pos]
                        hashval[48 + bc + row] = w0[48 + pos]
                return

            def permute_p512(j, a, c0, c1, c2, c3, c4, c5, c6, c7):
                for i in range(7):
                    r = 7 * j + i
                    sub_shift_mix_4(a)
                    add_constants_4(r, a)
                    if r & 1:
                        a[3], a[7], a[11], a[15] = a[3] ^ c4, a[7] ^ c5, a[11] ^ c6, a[15] ^ c7
                    else:
                        a[3], a[7], a[11], a[15] = a[3] ^ c0, a[7] ^ c1, a[11] ^ c2, a[15] ^ c3
                    swap_columns512(a)
                sub_shift_mix_4(a)
                swap_columns512(a)
                return

            def permute_q512(j, a, c0, c1, c2, c3, c4, c5, c6, c7):
                for i in range(3):
                    r = 42 + 3 * j + i
                    sub_shift_mix_4(a)
                    add_constants_4(r, a)
                    if r & 1:
                        a[3], a[7], a[11], a[15] = a[3] ^ c4, a[7] ^ c5, a[11] ^ c6, a[15] ^ c7
                    else:
                        a[3], a[7], a[11], a[15] = a[3] ^ c0, a[7] ^ c1, a[11] ^ c2, a[15] ^ c3
                    swap_columns512(a)
                sub_shift_mix_4(a)
                swap_columns512(a)
                return

            w0 = [0] * 64
            w1 = [0] * 64
            w2 = [0] * 64
            w3 = [0] * 64
            w4 = [0] * 64
            w5 = [0] * 64

            expand_message512(self.hash, buffer, w0, w1, w2, w3, w4, w5)

            c0 = (counter >> 56) & 0xff
            c1 = (counter >> 48) & 0xff
            c2 = (counter >> 40) & 0xff
            c3 = (counter >> 32) & 0xff
            c4 = (counter >> 24) & 0xff
            c5 = (counter >> 16) & 0xff
            c6 = (counter >> 8) & 0xff
            c7 = counter & 0xff

            permute_p512(0, w0, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p512(1, w1, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p512(2, w2, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p512(3, w3, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p512(4, w4, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_p512(5, w5, c0, c1, c2, c3, c4, c5, c6, c7)

            xor_state_4(w0, w1)
            xor_state_4(w0, w2)
            xor_state_4(w3, w4)
            xor_state_4(w3, w5)

            permute_q512(0, w0, c0, c1, c2, c3, c4, c5, c6, c7)
            permute_q512(1, w3, c0, c1, c2, c3, c4, c5, c6, c7)

            xor_state_4(w0, w3)
            store_hash512(self.hash, w0)
            return

    class Lane224(LaneBase):
        digest_bits = 224
        block_size = 64

    class Lane256(LaneBase):
        digest_bits = 256
        block_size = 64

    class Lane384(LaneBase):
        digest_bits = 384
        block_size = 128

    class Lane512(LaneBase):
        digest_bits = 512
        block_size = 128

    class FastHashBase:
        block_size = 8

        def __init__(self, data=b"", seed=0):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.buf = bytearray()
            self.msg_len = 0
            self.seed = seed
            self.value = 0
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__(seed=self.seed)
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            other.value = self.value
            return other

        def fasthash64(self, message, seed):

            def mix64(h):
                mix_const = 0x2127_599b_f432_5c37
                h &= 0xffff_ffff_ffff_ffff
                h ^= (h >> 23)
                h = (h * mix_const) & 0xffff_ffff_ffff_ffff
                h ^= (h >> 47)
                return h

            m = 0x8803_55f2_1e6d_1965
            length = len(message)

            h = (seed & 0xffff_ffff_ffff_ffff) ^ ((length * m) & 0xffff_ffff_ffff_ffff)

            index = 0
            end = length & ~7
            while index < end:
                v = struct.unpack_from("<Q", message, index)[0]
                index += 8
                h ^= mix64(v)
                h = (h * m) & 0xffff_ffff_ffff_ffff

            rem = length & 7
            if rem:
                tail = message[end:end + rem]
                v = 0
                for i in range(rem):
                    v ^= tail[i] << (8 * i)
                h ^= mix64(v)
                h = (h * m) & 0xffff_ffff_ffff_ffff

            h = mix64(h)
            return h

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.buf.extend(data)
            self.msg_len += len(data)
            return self

        def finalize(self):
            message = bytes(self.buf)
            self.value = self.compute_value(message, self.seed)
            return

        def digest(self):
            c = self.copy()
            c.finalize()
            return struct.pack(self.pack_format, c.value)

        def hexdigest(self):
            return self.digest().hex()

    class FastHash64(FastHashBase):
        digest_size = 8
        pack_format = "<Q"

        def compute_value(self, message, seed):
            return self.fasthash64(message, seed)

    class FastHash32(FastHashBase):
        digest_size = 4
        pack_format = "<I"

        def compute_value(self, message, seed):
            seed &= 0xffff_ffff
            h = self.fasthash64(message, seed)
            v = (h - (h >> 32)) & 0xffff_ffff
            return v

    class SuperFastHash:
        block_size = 4
        digest_size = 4

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.buf = bytearray()
            self.msg_len = 0
            self.value = 0
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            other.value = self.value
            return other

        def u32(self, x):
            x &= 0xffff_ffff
            return x

        def signed_char(self, x):
            x &= 0xff
            if x & 0x80:
                return x - 0x100
            return x

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.buf.extend(data)
            self.msg_len += len(data)
            return self

        def finalize(self):
            message = bytes(self.buf)
            length = len(message)

            index = 0
            digest = self.u32(length)

            for _ in range(length >> 2):
                w1 = message[index] | (message[index + 1] << 8)
                w2 = message[index + 2] | (message[index + 3] << 8)
                index += 4

                digest = self.u32(digest + w1)
                digest ^= self.u32(digest << 16) ^ self.u32(w2 << 11)
                digest = self.u32(digest + (digest >> 11))

            rem = length & 3
            if rem == 3:
                digest = self.u32(digest + (message[index] | (message[index + 1] << 8)))
                digest ^= self.u32(digest << 16)
                digest ^= self.u32(self.signed_char(message[index + 2]) << 18)
                digest = self.u32(digest + (digest >> 11))
            elif rem == 2:
                digest = self.u32(digest + (message[index] | (message[index + 1] << 8)))
                digest ^= self.u32(digest << 11)
                digest = self.u32(digest + (digest >> 17))
            elif rem == 1:
                digest = self.u32(digest + self.signed_char(message[index]))
                digest ^= self.u32(digest << 10)
                digest = self.u32(digest + (digest >> 1))

            digest ^= self.u32(digest << 3)
            digest = self.u32(digest + (digest >> 5))
            digest ^= self.u32(digest << 4)
            digest = self.u32(digest + (digest >> 17))
            digest ^= self.u32(digest << 25)
            digest = self.u32(digest + (digest >> 6))

            self.value = digest
            return

        def digest(self):
            c = self.copy()
            c.finalize()
            return struct.pack("<I", c.value)

        def hexdigest(self):
            return self.digest().hex()

