    class FugueBase:
        state_words = 36  # Fugue-384/512: 36, Fugue-224/256: 30

        @classmethod
        def ensure_tables(cls):
            if hasattr(Hash.FugueBase, "T"):
                return

            def rol8(x, n):
                x &= 0xff
                n &= 7
                return ((x << n) | (x >> (8 - n))) & 0xff

            def gf_mul(a, b):
                a &= 0xff
                b &= 0xff
                res = 0
                for _ in range(8):
                    if b & 1:
                        res ^= a
                    hi = a & 0x80
                    a = (a << 1) & 0xff
                    if hi:
                        a ^= 0x1b
                    b >>= 1
                return res & 0xff

            def gf_pow(a, e):
                res = 1
                base = a & 0xff
                while e:
                    if e & 1:
                        res = gf_mul(res, base)
                    base = gf_mul(base, base)
                    e >>= 1
                return res & 0xff

            def linear_map(U):
                M = ((1, 4, 7, 1), (1, 1, 4, 7), (7, 1, 1, 4), (4, 7, 1, 1))
                V = [[0] * 4 for _ in range(4)]
                for i in range(4):
                    for j in range(4):
                        acc = 0
                        for k in range(4):
                            coeff = M[i][k]
                            if coeff == 1:
                                acc ^= U[k][j]
                            else:
                                acc ^= gf_mul(U[k][j], coeff)
                        V[i][j] = acc & 0xff
                d = [0] * 4
                for i in range(4):
                    acc = 0
                    for j in range(4):
                        if j != i:
                            acc ^= U[i][j]
                    d[i] = acc & 0xff
                W = [[0] * 4 for _ in range(4)]
                for i in range(4):
                    for j in range(4):
                        coeff = M[j][i]
                        add = d[i] if coeff == 1 else gf_mul(d[i], coeff)
                        W[i][j] = (V[i][j] ^ add) & 0xff
                for i in range(4):
                    n = i & 3
                    if n:
                        W[i] = W[i][n:] + W[i][:n]
                y0 = ((W[0][0] << 24) | (W[1][0] << 16) | (W[2][0] << 8) | W[3][0]) & 0xffff_ffff
                y1 = ((W[0][1] << 24) | (W[1][1] << 16) | (W[2][1] << 8) | W[3][1]) & 0xffff_ffff
                y2 = ((W[0][2] << 24) | (W[1][2] << 16) | (W[2][2] << 8) | W[3][2]) & 0xffff_ffff
                y3 = ((W[0][3] << 24) | (W[1][3] << 16) | (W[2][3] << 8) | W[3][3]) & 0xffff_ffff
                return y0, y1, y2, y3

            sbox = [0] * 256
            for x in range(256):
                inv = 0 if x == 0 else gf_pow(x, 254)
                y = inv & 0xff
                sb = (y ^ rol8(y, 1) ^ rol8(y, 2) ^ rol8(y, 3) ^ rol8(y, 4) ^ 0x63)
                sbox[x] = sb & 0xff

            Hash.FugueBase.sbox = sbox

            T = [[[0 for _ in range(256)] for _ in range(4)] for _ in range(4)]
            for c in range(4):
                for r in range(4):
                    for val in range(256):
                        U = [[0]*4 for _ in range(4)]
                        U[r][c] = sbox[val]
                        y0, y1, y2, y3 = linear_map(U)
                        T[c][r][val] = (y0 << 96) | (y1 << 64) | (y2 << 32) | y3

            Hash.FugueBase.T = T
            return

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.ensure_tables()
            self.S = [0] * 36
            self.bit_count = 0
            self.partial = 0
            self.partial_len = 0
            self.rshift = 0
            iv = self.init_val
            if iv:
                n = self.state_words
                off = n - len(iv)
                for i, v in enumerate(iv):
                    self.S[off + i] = v & 0xffff_ffff
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.S = list(self.S)
            other.bit_count = self.bit_count
            other.partial = self.partial
            other.partial_len = self.partial_len
            other.rshift = self.rshift
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            self.bit_count = (
                self.bit_count + ((len(data) & 0xffff_ffff_ffff_ffff) << 3)
            ) & 0xffff_ffff_ffff_ffff
            for b in data:
                self.partial = ((self.partial << 8) | (b & 0xff)) & 0xffff_ffff
                self.partial_len += 1
                if self.partial_len == 4:
                    self.process(self.partial)
                    self.partial = 0
                    self.partial_len = 0
            return self

        def finalize(self):
            if self.partial_len != 0:
                while self.partial_len < 4:
                    self.partial = (self.partial << 8) & 0xffff_ffff
                    self.partial_len += 1
                self.process(self.partial)
                self.partial = 0
                self.partial_len = 0
            high = (self.bit_count >> 32) & 0xffff_ffff
            low = self.bit_count & 0xffff_ffff
            self.process(high)
            self.process(low)
            out = bytearray(self.digest_size)
            self.process_final(out)
            return bytes(out)

        def digest(self):
            c = self.copy()
            return c.finalize()

        def hexdigest(self):
            return self.digest().hex()

        def ror(self, rc, length):
            rc %= length
            if rc == 0:
                return
            tmp = self.S[length - rc:length]
            self.S[rc:length] = self.S[0:length - rc]
            self.S[0:rc] = tmp
            return

        def cmix30(self):
            S = self.S
            S[0] ^= S[4]
            S[1] ^= S[5]
            S[2] ^= S[6]
            S[15] ^= S[4]
            S[16] ^= S[5]
            S[17] ^= S[6]
            for i in (0, 1, 2, 15, 16, 17):
                S[i] &= 0xffff_ffff
            return

        def cmix36(self):
            S = self.S
            S[0] ^= S[4]
            S[1] ^= S[5]
            S[2] ^= S[6]
            S[18] ^= S[4]
            S[19] ^= S[5]
            S[20] ^= S[6]
            for i in (0, 1, 2, 18, 19, 20):
                S[i] &= 0xffff_ffff
            return

        def smix(self, i0, i1, i2, i3):
            S = self.S
            x0 = S[i0]
            x1 = S[i1]
            x2 = S[i2]
            x3 = S[i3]

            Tp = self.T

            out = Tp[0][0][(x0 >> 24) & 0xff]
            out ^= Tp[0][1][(x0 >> 16) & 0xff]
            out ^= Tp[0][2][(x0 >> 8) & 0xff]
            out ^= Tp[0][3][x0 & 0xff]

            out ^= Tp[1][0][(x1 >> 24) & 0xff]
            out ^= Tp[1][1][(x1 >> 16) & 0xff]
            out ^= Tp[1][2][(x1 >> 8) & 0xff]
            out ^= Tp[1][3][x1 & 0xff]

            out ^= Tp[2][0][(x2 >> 24) & 0xff]
            out ^= Tp[2][1][(x2 >> 16) & 0xff]
            out ^= Tp[2][2][(x2 >> 8) & 0xff]
            out ^= Tp[2][3][x2 & 0xff]

            out ^= Tp[3][0][(x3 >> 24) & 0xff]
            out ^= Tp[3][1][(x3 >> 16) & 0xff]
            out ^= Tp[3][2][(x3 >> 8) & 0xff]
            out ^= Tp[3][3][x3 & 0xff]

            S[i0] = (out >> 96) & 0xffff_ffff
            S[i1] = (out >> 64) & 0xffff_ffff
            S[i2] = (out >> 32) & 0xffff_ffff
            S[i3] = out & 0xffff_ffff
            return

        def process_final_common(self, out, state_len, init_rot_mul, cmix_fn, pre_rounds, loop_steps, final_xors, out_words):

            def xor_from_zero(indices):
                s0 = self.S[0]
                for idx in indices:
                    self.S[idx] ^= s0
                return

            def encode_words(out, indices):
                for pos, idx in enumerate(indices):
                    off = pos * 4
                    if off >= len(out):
                        break
                    x = self.S[idx]
                    out[off + 0] = (x >> 24) & 0xff
                    out[off + 1] = (x >> 16) & 0xff
                    out[off + 2] = (x >> 8) & 0xff
                    out[off + 3] = x & 0xff
                return

            self.ror(init_rot_mul * self.rshift, state_len)

            for _ in range(pre_rounds):
                self.ror(3, state_len)
                cmix_fn()
                self.smix(0, 1, 2, 3)

            for _ in range(13):
                for xor_indices, rot in loop_steps:
                    xor_from_zero(xor_indices)
                    self.ror(rot, state_len)
                    self.smix(0, 1, 2, 3)

            xor_from_zero(final_xors)
            encode_words(out, out_words)
            return

