    class RadioGatunBase:
        digest_size = 32
        blank_rounds = 16

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.word_bytes = self.word_bits // 8
            if self.block_size is None:
                self.block_size = self.word_bytes * 3
            self.word_mask = (1 << self.word_bits) - 1
            self.mill = [0] * 0x13
            self.belt = [0] * (13 * 3)
            self.buf = bytearray()
            self.is_finalized = False
            self.phase = 0
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.mill = list(self.mill)
            other.belt = list(self.belt)
            other.buf = bytearray(self.buf)
            other.is_finalized = self.is_finalized
            other.phase = self.phase
            return other

        def update(self, data):
            if self.is_finalized:
                raise ValueError("hash object already finalized")
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.buf.extend(data)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[: self.block_size])
                del self.buf[: self.block_size]
                self.absorb_block(block)
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return c.squeeze(self.digest_size)

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            if self.is_finalized:
                return
            data = bytes(self.buf) + b"\x01"
            self.buf = bytearray()
            rem = len(data) % self.block_size
            if rem != 0:
                data += b"\x00" * (self.block_size - rem)
            for off in range(0, len(data), self.block_size):
                self.absorb_block(data[off : off + self.block_size])
            for _ in range(self.blank_rounds):
                self.beltmill()
            self.is_finalized = True
            self.phase = 0
            return

        def squeeze(self, nbytes):

            def get_word():
                if self.phase == 0:
                    self.beltmill()
                    self.phase = 1
                out = self.mill[self.phase]
                self.phase += 1
                if self.phase > 2:
                    self.phase = 0
                return out

            if not self.is_finalized:
                self.finalize()
            out = bytearray()
            while len(out) < nbytes:
                w = get_word()
                out.extend(w.to_bytes(self.word_bytes, "little"))
            return bytes(out[:nbytes])

        def beltmill(self):

            def ror(x, r):
                if r == 0:
                    return x
                return ((x >> r) | (x << (self.word_bits - r))) & self.word_mask

            def mill_func(mill):
                A = [0] * 19
                for i in range(19):
                    A[i] = mill[i] ^ (mill[(i + 1) % 19] | (mill[(i + 2) % 19] ^ self.word_mask))
                a = [0] * 19
                for i in range(19):
                    a[i] = ror(A[(7 * i) % 19], self.rotate[i])
                for i in range(19):
                    A[i] = a[i] ^ a[(i + 1) % 19] ^ a[(i + 4) % 19]
                A[0] ^= 1
                return A

            old_belt = self.belt
            old_mill = self.mill
            new_belt = [0] * (13 * 3)
            for i in range(13):
                src = (i - 1) % 13
                new_belt[i * 3 : (i + 1) * 3] = old_belt[src * 3 : (src + 1) * 3]
            for i in range(12):
                stage = i + 1
                word = i % 3
                new_belt[stage * 3 + word] ^= old_mill[i + 1]
            new_mill = mill_func(old_mill)
            base = 12 * 3
            new_mill[13] ^= old_belt[base + 0]
            new_mill[14] ^= old_belt[base + 1]
            new_mill[15] ^= old_belt[base + 2]
            self.belt = new_belt
            self.mill = new_mill
            return

        def absorb_block(self, block):
            w = self.word_bytes
            p0 = int.from_bytes(block[0 * w:1 * w], "little")
            p1 = int.from_bytes(block[1 * w:2 * w], "little")
            p2 = int.from_bytes(block[2 * w:3 * w], "little")
            self.belt[0] ^= p0
            self.belt[1] ^= p1
            self.belt[2] ^= p2
            self.mill[16] ^= p0
            self.mill[17] ^= p1
            self.mill[18] ^= p2
            self.beltmill()
            return

