        def finalize(self):
            if (len(self.buf) > 0) or (self.pad_type == 2):
                if self.pad_type == 2:
                    self.buf.append(0x80)
                while len(self.buf) < 8:
                    self.buf.append(0x00)
                self.compress(bytes(self.buf[:8]))
                del self.buf[:8]
