            y[9] = x[pi[9]]
            y[10] = x[pi[10]]
            y[11] = x[pi[11]]
            y[12] = x[pi[12]]
            y[13] = x[pi[13]]
            y[14] = x[pi[14]]
            y[15] = x[pi[15]]
            y[16] = x[pi[16]]
            y[17] = x[pi[17]]
            y[18] = x[pi[18]]
            y[19] = x[pi[19]]
            y[20] = x[pi[20]]
            y[21] = x[pi[21]]
            y[22] = x[pi[22]]
