            value = ((value >> 36) ^ value) & 0xf_ffff_ffff
            value = ((value >> 18) ^ value) & 0x3f_fff
            value = ((value >> 12) ^ value) & 0xfff
            value = ((value >> 6) ^ value) & 0x3f
