        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            n = (self.digest_bits >> 3) - 1
            self.points = [0, 1, n - 3, n]
            self.partial_bits = 0
            self.partial_byte = 0
            self.state = bytearray(range(n + 1))
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.points = self.points[:]
            other.partial_bits = self.partial_bits
            other.partial_byte = self.partial_byte
            other.state = bytearray(self.state)
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            if isinstance(data, memoryview):
                data = data.tobytes()
            else:
                data = bytes(data)
            bit_length = len(data) * 8
            if bit_length < 0:
                raise ValueError("bit_length must be non-negative")
            if bit_length > len(data) * 8:
                raise ValueError("bit_length exceeds input size")
            x1, x2, x3, x4 = self.points
            bits = self.partial_bits
            last = self.partial_byte
            n = (self.digest_bits >> 3) - 8
            state_len = n + 8
            full_bytes = (bit_length + bits) >> 3
            state = self.state
            sbox = self.sbox
            index = 0
            while index < full_bytes:
                value = data[index]
                if bits != 0:
                    mixed = last ^ (value >> bits)
                    last = (value << (8 - bits)) & 0xff
                    state[x1] = (sbox[(state[x1] - state[x2] - state[x3] + state[x4]) & 0xff] + mixed) & 0xff
                else:
                    state[x1] = (sbox[(state[x1] - state[x2] - state[x3] + state[x4]) & 0xff] + value) & 0xff
                for i in range(4):
                    x1 += 1
                    x2 += 1
                    x3 += 1
                    x4 += 1
                    if x1 == state_len:
                        x1 = 0
                    if x2 == state_len:
                        x2 = 0
                    if x3 == state_len:
                        x3 = 0
                    if x4 == state_len:
                        x4 = 0
                    if i != 3:
                        state[x1] = sbox[(state[x1] - state[x2] - state[x3] + state[x4]) & 0xff]
                index += 1
            if bits != 0:
                self.partial_bits = bit_length + bits - (index << 3)
                if self.partial_bits != 0:
                    if index != 0:
                        self.partial_byte = ((last >> (8 - self.partial_bits)) << (8 - self.partial_bits)) & 0xff
                    else:
                        mixed = last ^ (data[index] >> bits)
                        self.partial_byte = ((mixed >> (8 - self.partial_bits)) << (8 - self.partial_bits)) & 0xff
                else:
                    self.partial_byte = 0
            else:
                self.partial_bits = bit_length - ((bit_length >> 3) << 3)
                if self.partial_bits != 0:
                    self.partial_byte = ((data[index] >> (8 - self.partial_bits)) << (8 - self.partial_bits)) & 0xff
                else:
                    self.partial_byte = 0
            self.points = [x1, x2, x3, x4]
            return self

        def finalize(self):
            x1, x2, x3, x4 = self.points
            bits = self.partial_bits
            last = self.partial_byte
            n = (self.digest_bits >> 3) - 8
            state_len = n + 8
            final_len = self.digest_bits >> 1
            state = self.state
            sbox = self.sbox
            repeated = bytes(state[:state_len]) * 4
            index = 0
            while index < final_len:
                value = repeated[index]
                if bits != 0:
                    mixed = last ^ (value >> bits)
                    last = (value << (8 - bits)) & 0xff
                    state[x1] = (sbox[(state[x1] - state[x2] - state[x3] + state[x4]) & 0xff] + mixed) & 0xff
                else:
                    state[x1] = (sbox[(state[x1] - state[x2] - state[x3] + state[x4]) & 0xff] + value) & 0xff
                x1 += 1
                x2 += 1
                x3 += 1
                x4 += 1
                if x1 == state_len:
                    x1 = 0
                if x2 == state_len:
                    x2 = 0
                if x3 == state_len:
                    x3 = 0
                if x4 == state_len:
                    x4 = 0
                index += 1
            self.points = [x1, x2, x3, x4]
            return bytes(state[:state_len])

        def digest(self):
            other = self.copy()
            result = other.finalize()
            return result

        def hexdigest(self):
            result = self.digest().hex()
            return result

