        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.h = list(self.h_init)
            self.hash_words = list(self.hash_init)
            self.buf = bytearray()
            self.msg_len = 0
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.h = list(self.h)
            other.hash_words = list(self.hash_words)
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                self.compress(block)
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            out = bytearray()
            for word in c.hash_words:
                out.extend(word.to_bytes(8, "big"))
            return bytes(out[:self.digest_size])

        def hexdigest(self):
            return self.digest().hex()

        def get_q64(self, x, y, a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha, beta, gama, a_word, b_word, c_word):

            def get_f16(x, a, b, c):
                return [x[1] ^ a, x[0] ^ b ^ self.sbox[x[1] ^ c]]

            def get_f32(x, a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha, beta, gama):
                y0 = x[2] ^ ((alpha >> 8) & 0xff)
                y1 = x[3] ^ (alpha & 0xff)
                z = [
                    x[2] ^ ((gama >> 8) & 0xff),
                    x[3] ^ (gama & 0xff),
                ]
                f = get_f16(z, a3, b3, c3)
                z = get_f16(f, a2, b2, c2)
                f = get_f16(z, a1, b1, c1)
                return [y0, y1, x[0] ^ ((beta >> 8) & 0xff) ^ f[0], x[1] ^ (beta & 0xff) ^ f[1]]

            def get_f64(x, a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha, beta, gama, a_word, b_word, c_word):
                y = [
                    x[4] ^ ((a_word >> 24) & 0xff),
                    x[5] ^ ((a_word >> 16) & 0xff),
                    x[6] ^ ((a_word >> 8) & 0xff),
                    x[7] ^ (a_word & 0xff),
                ]
                z = [
                    x[4] ^ ((c_word >> 24) & 0xff),
                    x[5] ^ ((c_word >> 16) & 0xff),
                    x[6] ^ ((c_word >> 8) & 0xff),
                    x[7] ^ (c_word & 0xff),
                ]
                f = get_f32(z, a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha, beta, gama)
                return y + [
                    x[0] ^ ((b_word >> 24) & 0xff) ^ f[0],
                    x[1] ^ ((b_word >> 16) & 0xff) ^ f[1],
                    x[2] ^ ((b_word >> 8) & 0xff) ^ f[2],
                    x[3] ^ (b_word & 0xff) ^ f[3],
                ]

            z = [xb ^ yb for xb, yb in zip(x, y)]
            fp = get_f64(z[::-1], a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha, beta, gama, a_word, b_word, c_word)
            fz = fp[::-1]
            return [fb ^ yb for fb, yb in zip(fz, y)]

        def compile_words(self, message_words):

            def lintr(values):
                values = list(values)
                last = len(values) - 1
                t0, t1, t2, t3 = self.lintr_taps
                for _ in range(self.lintr_rounds):
                    pom = values[t0] ^ values[t1] ^ values[t2] ^ values[t3]
                    for i in range(last, 0, -1):
                        values[i] = values[i - 1]
                    values[0] = pom
                return values

            def ae(leader, values, a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha, beta, gama, a_word, b_word, c_word):
                out = [0] * len(values)
                m1 = leader

                for i, value in enumerate(values):
                    p = (value + m1) & 0xffff_ffff_ffff_ffff
                    m1 = value
                    q = self.get_q64(
                        list(p.to_bytes(8, "little")),
                        list(m1.to_bytes(8, "little")),
                        a1, b1, c1,
                        a2, b2, c2,
                        a3, b3, c3,
                        alpha, beta, gama,
                        a_word, b_word, c_word,
                    )
                    m1 = int.from_bytes(bytes(q), "little")
                    out[i] = m1

                return out

            def rae(leader, values, a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha, beta, gama, a_word, b_word, c_word):
                out = [0] * len(values)
                p = leader

                for i in range(len(values) - 1, -1, -1):
                    p = (p + values[i]) & 0xffff_ffff_ffff_ffff
                    q = self.get_q64(
                        list(values[i].to_bytes(8, "little")),
                        list(p.to_bytes(8, "little")),
                        a1, b1, c1,
                        a2, b2, c2,
                        a3, b3, c3,
                        alpha, beta, gama,
                        a_word, b_word, c_word,
                    )
                    p = int.from_bytes(bytes(q), "little")
                    out[i] = p

                return out

            chain_words = len(self.h)
            x = [0] * (chain_words * 4)

            for k in range(chain_words):
                x[k << 2] = message_words[k << 1]
                x[(k << 2) + 1] = self.h[k]
                x[(k << 2) + 2] = message_words[(k << 1) + 1]
                x[(k << 2) + 3] = self.hash_words[k]

            x = lintr(x)

            l1 = (x[0] + x[1]) & 0xffff_ffff_ffff_ffff
            l2 = (x[2] + x[3]) & 0xffff_ffff_ffff_ffff

            tmp = (x[4] + x[5]) & 0xffff_ffff_ffff_ffff
            a1 = (tmp >> 56) & 0xff
            b1 = (tmp >> 48) & 0xff
            c1 = (tmp >> 40) & 0xff
            a2 = (tmp >> 32) & 0xff
            b2 = (tmp >> 24) & 0xff
            c2 = (tmp >> 16) & 0xff
            a3 = (tmp >> 8) & 0xff
            b3 = tmp & 0xff
            c3 = a1

            tmp = (x[6] + x[7]) & 0xffff_ffff_ffff_ffff
            alpha1 = (tmp >> 48) & 0xffff
            beta1 = (tmp >> 32) & 0xffff
            gama1 = (tmp >> 16) & 0xffff
            alpha2 = tmp & 0xffff

            tmp = (x[8] + x[9]) & 0xffff_ffff_ffff_ffff
            beta2 = (tmp >> 48) & 0xffff
            gama2 = (tmp >> 32) & 0xffff

            tmp = (x[10] + x[11]) & 0xffff_ffff_ffff_ffff
            a_word1 = (tmp >> 32) & 0xffff_ffff
            b_word1 = tmp & 0xffff_ffff

            tmp = (x[12] + x[13]) & 0xffff_ffff_ffff_ffff
            c_word1 = (tmp >> 32) & 0xffff_ffff
            a_word2 = tmp & 0xffff_ffff

            tmp = (x[14] + x[15]) & 0xffff_ffff_ffff_ffff
            b_word2 = (tmp >> 32) & 0xffff_ffff
            c_word2 = tmp & 0xffff_ffff

            y = ae(l2, x, a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha1, beta1, gama1, a_word1, b_word1, c_word1)
            y = [((x & 0xffff_ffff) << 32) | (x >> 32) for x in y]
            x = rae(l1, y, a1, b1, c1, a2, b2, c2, a3, b3, c3, alpha2, beta2, gama2, a_word2, b_word2, c_word2)

            for i in range(chain_words):
                self.h[i] = x[(i << 2) + 1]
                self.hash_words[i] = x[(i << 2) + 3]
            return

        def compress(self, block):
            message_words = [
                int.from_bytes(block[i:i + 8], "little")
                for i in range(0, self.block_size, 8)
            ]
            self.compile_words(message_words)
            return

        def finalize(self):
            total_bits = self.msg_len * 8
            word_count = self.block_size // 8

            buf = bytearray(self.buf)
            buf.extend(b"\x00" * (self.block_size - len(buf)))

            words = [
                int.from_bytes(buf[i:i + 8], "little")
                for i in range(0, self.block_size, 8)
            ]

            i = len(self.buf)
            bit_mod_64 = total_bits % 64
            word_index = i >> 3

            if bit_mod_64 != 0:
                words[word_index] &= 0xffff_ffff_ffff_fffe >> (64 - bit_mod_64)
            else:
                words[word_index] = 0

            words[word_index] |= 1 << bit_mod_64

            if i > self.block_size - 17:
                if i < self.block_size - 8:
                    words[word_count - 1] = 0
                self.compile_words(words)
                i = 0
                words = [0] * word_count
            else:
                i = (i >> 3) + 1

            while i < word_count - 2:
                words[i] = 0
                i += 1

            words[word_count - 2] = 0
            words[word_count - 1] = total_bits

            self.compile_words(words)
            return

