        SIGMA7_5 = (15, 7, 9, 12, 3, 13, 10, 0, 4, 6, 1, 14, 2, 5, 8, 11)
        LEFT_SIGMAS_COMMON = (SIGMA0, SIGMA1, SIGMA2, SIGMA3)
        RIGHT_SIGMAS_COMMON = (SIGMA4, SIGMA5, SIGMA6, SIGMA7)
        INIT_S = (0, 0, 0, 0)

        @classmethod
        def ensure_tables(cls):
            if hasattr(Hash.SarmalBase, "G_TABLES"):
                return

            def gf_multiply(a, b):
                result = 0
                while b:
                    if b & 1:
                        result ^= a
                    a <<= 1
                    if a & 0x100:
                        a ^= 0x11d
                    b >>= 1
                return result

            constants = (1, 5, 6, 8, 9)
            mul_tables = {}
            for constant in constants:
                table = []
                for value in range(256):
                    table.append(gf_multiply(value, constant))
                mul_tables[constant] = tuple(table)
            tables = []
            for pos in range(8):
                pos_table = []
                for byte_value in range(256):
                    sboxed = cls.S[byte_value]
                    word = 0
                    for row in range(8):
                        out_byte = mul_tables[cls.MDS[row][pos]][sboxed]
                        word = (word << 8) | out_byte
                    pos_table.append(word)
                tables.append(tuple(pos_table))
            Hash.SarmalBase.G_TABLES = tuple(tables)
            return

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.h = list(self.INIT_H)
            self.c = list(self.INIT_C)
            self.s = list(self.INIT_S)
            self.t = 0
            self.msg_len = 0
            self.buf = bytearray()
            self.ensure_tables()
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.h = list(self.h)
            other.c = list(self.c)
            other.s = list(self.s)
            other.t = self.t
            other.msg_len = self.msg_len
            other.buf = bytearray(self.buf)
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            chunk = bytes(data)
            self.msg_len += len(chunk)
            self.buf.extend(chunk)
            while len(self.buf) >= self.block_size:
                block = bytes(self.buf[:self.block_size])
                del self.buf[:self.block_size]
                self.compress(block)
            return self

        def digest(self):
            clone = self.copy()
            clone.finalize()
            return clone.output_digest()

        def hexdigest(self):
            return self.digest().hex()

        def output_digest(self):
            state_bytes = b"".join(word.to_bytes(8, "big") for word in self.h)
            if self.digest_bits == 224:
                return state_bytes[-28:]
            return state_bytes[:self.digest_size]

        def finalize(self):
            messagebitlen = self.msg_len * 8
            block = bytearray(self.buf)

            if len(block) <= 118:
                block.append(0x80)
                while len(block) < 119:
                    block.append(0x00)
            else:
                block.append(0x80)
                while len(block) < 128:
                    block.append(0x00)
                self.compress(bytes(block))
                block = bytearray(119)

            if self.digest_bits == 224:
                block.append(0xe0)
            elif self.digest_bits == 256:
                block[118] |= 0x01
                block.append(0x00)
            elif self.digest_bits == 384:
                block[118] |= 0x01
                block.append(0x80)
            elif self.digest_bits == 512:
                block[118] |= 0x02
                block.append(0x00)
            else:
                raise ValueError("unsupported digest_bits")

            block.extend(messagebitlen.to_bytes(8, "big"))
            self.compress(bytes(block))
            self.buf.clear()
            return

        def compress(self, block):

            def g_func(value):
                tables = self.G_TABLES
                result = (
                    tables[0][(value >> 56) & 0xff] ^
                    tables[1][(value >> 48) & 0xff] ^
                    tables[2][(value >> 40) & 0xff] ^
                    tables[3][(value >> 32) & 0xff] ^
                    tables[4][(value >> 24) & 0xff] ^
                    tables[5][(value >> 16) & 0xff] ^
                    tables[6][(value >> 8) & 0xff] ^
                    tables[7][value & 0xff]
                )
                return result

            def mix(state, a, b, c, d):
                out1 = state[0] ^ a
                temp1 = g_func(out1)
                out2 = temp1 ^ state[1]
                temp2 = state[2] ^ b
                out3 = (temp1 + temp2) & 0xffff_ffff_ffff_ffff
                out4 = (state[3] - temp1) & 0xffff_ffff_ffff_ffff
                out5 = state[4] ^ c
                temp2 = g_func(out5)
                out6 = temp2 ^ state[5]
                temp1 = state[6] ^ d
                out7 = (temp2 + temp1) & 0xffff_ffff_ffff_ffff
                out0 = (state[7] - temp2) & 0xffff_ffff_ffff_ffff
                return [out0, out1, out2, out3, out4, out5, out6, out7]

            def apply_sigmas(state, message_words, sigmas):
                current = state
                mw = message_words
                for sigma in sigmas:
                    current = mix(current, mw[sigma[0]], mw[sigma[1]], mw[sigma[2]], mw[sigma[3]])
                    current = mix(current, mw[sigma[4]], mw[sigma[5]], mw[sigma[6]], mw[sigma[7]])
                    current = mix(current, mw[sigma[8]], mw[sigma[9]], mw[sigma[10]], mw[sigma[11]])
                    current = mix(current, mw[sigma[12]], mw[sigma[13]], mw[sigma[14]], mw[sigma[15]])
                return current

            message_words = [int.from_bytes(block[i * 8:(i + 1) * 8], "big") for i in range(16)]

            left = [self.h[0], self.h[1], self.h[2], self.h[3], self.s[0], self.s[1], self.c[0], self.t]
            right = [self.h[4], self.h[5], self.h[6], self.h[7], self.s[2], self.s[3], self.c[1], self.t]

            left = apply_sigmas(left, message_words, self.LEFT_SIGMAS_COMMON)
            right = apply_sigmas(right, message_words, self.RIGHT_SIGMAS_COMMON)

            if self.digest_bits in (384, 512):
                left = apply_sigmas(left, message_words, (self.SIGMA3_5,))
                right = apply_sigmas(right, message_words, (self.SIGMA7_5,))

            for i in range(8):
                right[i] ^= left[i]

            for i in range(8):
                self.h[i] ^= right[i]

            self.t += 1024
            return

