        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.digest_size = self.digest_bits // 8
            self.h = list(self.ivs[self.digest_bits])
            self.buf = bytearray()
            self.msg_len = 0
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.h = self.h[:]
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            self.msg_len += len(data)
            self.buf.extend(data)
            while len(self.buf) >= 512:
                block = bytes(self.buf[:512])
                del self.buf[:512]
                self.compress(block)
            return self

        def digest(self):
            other = self.copy()
            other.finalize()
            return struct.pack("<%dI" % (other.digest_size // 4), *other.h[:other.digest_size // 4])

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            bit_len = self.msg_len * 8
            if bit_len > 0xffff_ffff_ffff_ffff:
                raise OverflowError("message is too long for the reference-compatible length field")
            self.buf.append(0x80)
            if len(self.buf) > 496:
                self.buf.extend(b"\x00" * (512 - len(self.buf)))
                self.compress(bytes(self.buf))
                self.buf.clear()
            self.buf.extend(b"\x00" * (504 - len(self.buf)))
            self.buf.extend(struct.pack(">Q", bit_len))
            self.compress(bytes(self.buf))
            self.buf.clear()
            return

        def compress(self, block):
            if len(block) != 512:
                raise ValueError("block must be exactly 512 bytes")

            def rol32(x, n):
                x &= 0xffff_ffff
                return ((x << n) | (x >> (32 - n))) & 0xffff_ffff

            def fr1(x):
                return rol32(x, 3) ^ rol32(x, 13) ^ rol32(x, 29)

            def fr2(x):
                return rol32(x, 5) ^ rol32(x, 19) ^ rol32(x, 27)

            def f1(x, y, z):
                return (x & (y | z)) | (y & z)

            def f2(x, y, z):
                return ((y ^ 0xffff_ffff) & (x | z)) | (x & z)

            mask = 0xffff_ffff
            sbox = self.sbox
            ktab = self.k
            rounds = self.rounds
            hstate = self.h
            msg = struct.unpack("<128I", block)
            h = hstate[:]
            w = [0] * (rounds * 2)
            xa = [0] * 8

            for r in range(8):
                a = (h[r] + h[r + 8] + msg[r] + msg[r + 8] + msg[r + 16] + msg[r + 24] + msg[r + 32]
                     + msg[r + 40] + msg[r + 48] + msg[r + 56]) & mask
                b = (h[r + 16] + h[r + 24] + msg[r + 64] + msg[r + 72] + msg[r + 80] + msg[r + 88] + msg[r + 96]
                     + msg[r + 104] + msg[r + 112] + msg[r + 120]) & mask
                xa[r] = (fr1(a) + fr2(b)) & mask

            for kidx in range(rounds // 2):
                t = kidx * 4
                xb0 = xa[0] ^ xa[3] ^ xa[6] ^ xa[7]
                xb1 = xa[0] ^ xa[1] ^ xa[3] ^ xa[6]
                xb2 = xa[0] ^ xa[1] ^ xa[3] ^ xa[4] ^ xa[5]
                xb3 = xa[4] ^ xa[5] ^ xa[6] ^ xa[7]
                xb4 = xa[0] ^ xa[2] ^ xa[7]
                xb5 = xa[2] ^ xa[5] ^ xa[6] ^ xa[7]
                xb6 = xa[2] ^ xa[3] ^ xa[4] ^ xa[6] ^ xa[7]
                xb7 = xa[0] ^ xa[4] ^ xa[6]

                w[t] = (f1(xb0, xb1, ktab[t % 256]) + msg[t % 128]) & mask
                w[t + 1] = (f2(xb2, xb3, ktab[(t + 1) % 256]) + msg[(t + 1) % 128]) & mask
                w[t + 2] = (f1(xb4, xb5, ktab[(t + 2) % 256]) + msg[(t + 2) % 128]) & mask
                w[t + 3] = (f2(xb6, xb7, ktab[(t + 3) % 256]) + msg[(t + 3) % 128]) & mask
                xa = [xb0, xb1, xb2, xb3, xb4, xb5, xb6, xb7]

            s = 0
            for r in range(rounds):
                t = r * 2
                c = (w[t] + w[t + 1]) & mask
                s ^= sbox[(c ^ (c >> 8) ^ (c >> 16) ^ (c >> 24)) & 0xff]
                p = s % 16
                q = s >> 4

                if (r % 2) == 0:
                    a = (f1(h[p], h[r % 32], fr1(h[q + 16])) + w[t] + ktab[s]) & mask
                    b = (f1(h[q], h[(r + 8) % 32], fr2(h[p + 16])) + w[t + 1]) & mask
                else:
                    a = (f2(h[p], h[r % 32], fr1(h[q + 16])) + w[t] + ktab[s]) & mask
                    b = (f2(h[q], h[(r + 8) % 32], fr2(h[p + 16])) + w[t + 1]) & mask

                h[r % 32] = (h[r % 32] + b) & mask
                h[(r + 16) % 32] ^= (a + b) & mask

            for i in range(32):
                hstate[i] = (hstate[i] + h[i]) & mask
            return

