            b = a + 1
            ds[a] = (ds[a] * self.P) & 0xffff_ffff_ffff_ffff
            ds[a] = self.ror64(ds[a], 23)
            ds[a] = (ds[a] * self.Q) & 0xffff_ffff_ffff_ffff
