    class Gimli24:
        digest_size = 32

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.state = bytearray(48)
            self.buf = bytearray()
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.state = bytearray(self.state)
            other.buf = bytearray(self.buf)
            return other

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            if not data:
                return self

            state = self.state
            data_pos = 0
            data_len = len(data)

            if self.buf:
                take = min(16 - len(self.buf), data_len)
                self.buf.extend(data[:take])
                data_pos = take
                if len(self.buf) == 16:
                    for i, b in enumerate(self.buf):
                        state[i] ^= b
                    self.permutation()
                    self.buf.clear()

            while data_pos + 16 <= data_len:
                block = data[data_pos:data_pos + 16]
                for i, b in enumerate(block):
                    state[i] ^= b
                self.permutation()
                data_pos += 16

            if data_pos < data_len:
                self.buf.extend(data[data_pos:])
            return self

        def digest(self):
            c = self.copy()
            c.finalize()
            return bytes(c.state[:16]) + c.squeeze_more()

        def hexdigest(self):
            return self.digest().hex()

        def finalize(self):
            state = self.state
            buf = self.buf
            for i, b in enumerate(buf):
                state[i] ^= b
            state[len(buf)] ^= 0x01
            state[47] ^= 0x01
            self.permutation()
            buf.clear()
            return

        def squeeze_more(self):
            self.permutation()
            return bytes(self.state[:16])

        def permutation(self):

            def rol32(x, n):
                return ((x << n) | (x >> (32 - n))) & 0xffff_ffff

            state = self.state
            s = [int.from_bytes(state[i:i + 4], "little") for i in range(0, 48, 4)]

            for round_num in range(24, 0, -1):
                for col in range(4):
                    x = rol32(s[col], 24)
                    y = rol32(s[col + 4], 9)
                    z = s[col + 8]
                    s[col + 8] = (x ^ (z << 1) ^ ((y & z) << 2)) & 0xffff_ffff
                    s[col + 4] = (y ^ x ^ ((x | z) << 1)) & 0xffff_ffff
                    s[col] = (z ^ y ^ ((x & y) << 3)) & 0xffff_ffff

                if (round_num & 3) == 0:
                    s[0], s[1] = s[1], s[0]
                    s[2], s[3] = s[3], s[2]
                    s[0] ^= 0x9e37_7900 | round_num
                elif (round_num & 3) == 2:
                    s[0], s[2] = s[2], s[0]
                    s[1], s[3] = s[3], s[1]

            for i, x in enumerate(s):
                state[i * 4:i * 4 + 4] = x.to_bytes(4, "little")
            return

    class Heron256:
        digest_size = 32

        mask64 = 0xffff_ffff_ffff_ffff
        mask512 = (1 << 512) - 1
        max_msg_len = (1 << 61) - 1

        ct0_ct1 = 0x14f1_c272_3279_c419
        ct2_ct3 = 0x4b8e_a41d_0cc8_0863
        ct4_bytes = (
            0xd2, 0x80, 0x62, 0xe1, 0xe7, 0x1d, 0x3d, 0xda, 0xe3, 0xc4, 0xd1, 0x58, 0xa7, 0xf0, 0x67, 0xac,
            0x94, 0x93, 0x50, 0x56, 0x8e, 0xe5, 0xc6, 0x3d, 0xf5, 0xa0, 0xce, 0xc3, 0xd3, 0x3d, 0xa5, 0xa7,
            0x7d, 0xe8, 0x92, 0xac, 0xe8, 0xfd, 0x9b, 0x12, 0xfb, 0x62, 0x5a, 0x84, 0xf1, 0x5a, 0x53, 0x23,
            0xd9, 0x3d, 0x39, 0x95, 0x9a, 0x48, 0x5a, 0x71, 0xda, 0xb8, 0xec, 0xd1, 0x9d, 0x9b, 0x3e, 0x2e,
        )
        ct4 = int.from_bytes(bytes(ct4_bytes), "big")

        def __init__(self, data=b""):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            self.s0 = self.ct0_ct1
            self.s1 = self.ct2_ct3
            self.s2 = self.ct0_ct1
            self.s3 = self.ct2_ct3
            self.s4 = self.ct4
            self.buf = bytearray()
            self.msg_len = 0
            if data:
                self.update(data)
            return

        def copy(self):
            other = self.__class__()
            other.s0 = self.s0
            other.s1 = self.s1
            other.s2 = self.s2
            other.s3 = self.s3
            other.s4 = self.s4
            other.buf = bytearray(self.buf)
            other.msg_len = self.msg_len
            return other

        def hash_byte(self, mbyte):
            s0 = self.s0
            s1 = self.s1
            s2 = self.s2
            s3 = self.s3
            s4 = self.s4
            mask64 = self.mask64
            mask512 = self.mask512

            for i in range(8):
                m = (mbyte >> i) & 1

                x0 = (s0 >> 33) & 1
                y0 = (s0 >> 34) & 1
                x1 = (s1 >> 31) & 1
                y1 = (s1 >> 39) & 1
                x2 = (s2 >> 32) & 1
                y2 = (s2 >> 59) & 1
                x3 = (s3 >> 48) & 1
                y3 = (s3 >> 49) & 1

                a = 1 ^ (x0 & y0) ^ (x1 & y1) ^ (x2 & y2) ^ (x3 & y3) ^ m
                b = (x0 & y2) ^ (y0 & y3) ^ (x1 & x3) ^ (y1 & x2) ^ ((s0 >> 31) & 1)

                f0 = (s0 >> 63) ^ ((s0 >> 32) & 1) ^ ((s0 >> 31) & 1) ^ ((s1 >> 50) & 1)
                f1 = (s1 >> 63) ^ ((s1 >> 35) & 1) ^ ((s1 >> 33) & 1) ^ ((s2 >> 62) & 1)
                f2 = (s2 >> 63) ^ ((s2 >> 41) & 1) ^ ((s2 >> 36) & 1) ^ ((s3 >> 37) & 1)
                f3 = (s3 >> 63) ^ ((s3 >> 55) & 1) ^ ((s3 >> 44) & 1) ^ ((s0 >> 32) & 1)

                s0 = ((s0 << 1) & mask64) | f0
                s1 = ((s1 << 1) & mask64) | f1
                s2 = ((s2 << 1) & mask64) | f2
                s3 = ((s3 << 1) & mask64) | f3

                d = s4 >> 511
                s4 = ((s4 << 1) & mask512) | (d ^ b)
                b = d

                if a:
                    s0 ^= 1
                    s2 ^= 1
                if b:
                    s1 ^= 1
                    s3 ^= 1

            self.s0 = s0
            self.s1 = s1
            self.s2 = s2
            self.s3 = s3
            self.s4 = s4
            return

        def process_block(self, block):
            for x in block:
                self.hash_byte(x)
            for _ in range(4):
                self.hash_byte(0)
            return

        def update(self, data):
            if not isinstance(data, (bytes, bytearray, memoryview)):
                raise TypeError("data must be bytes-like")
            data = bytes(data)
            if self.msg_len + len(data) > self.max_msg_len:
                raise OverflowError("message is too long")
            self.msg_len += len(data)

            offset = 0
            data_len = len(data)
            if self.buf:
                need = 4 - len(self.buf)
                take = min(need, data_len)
                self.buf.extend(data[:take])
                offset = take
                if len(self.buf) < 4:
                    return self
                self.process_block(self.buf)
                self.buf.clear()

            while offset + 4 <= data_len:
                self.process_block(data[offset:offset + 4])
                offset += 4

            if offset < data_len:
                self.buf.extend(data[offset:])
            return self

        def finalize(self):
            if self.msg_len == 0:
                for _ in range(4):
                    self.hash_byte(0)
            elif self.buf:
                buf_len = len(self.buf)
                for x in self.buf:
                    self.hash_byte(x)
                for _ in range(4 - buf_len):
                    self.hash_byte(0)
                for _ in range(4):
                    self.hash_byte(0)
                self.buf.clear()

            bit_len_bytes = (self.msg_len * 8).to_bytes(8, "big")
            for i in range(128):
                if i < 64:
                    u = bit_len_bytes[i & 7] ^ self.ct4_bytes[i]
                else:
                    u = bit_len_bytes[i & 7]

                tmp = 0
                s4 = self.s4
                for j in range(8):
                    tmp |= ((s4 >> (255 - j)) & 1) << j
                self.hash_byte(u ^ tmp)
            return

        def digest(self):
            c = self.copy()
            c.finalize()
            out = bytearray(32)
            s4 = c.s4
            for i in range(32):
                x = 0
                for j in range(8):
                    x |= ((s4 >> (255 - 8 * i - j)) & 1) << j
                out[i] = x
            return bytes(out)

        def hexdigest(self):
            return self.digest().hex()


